previewCss:
.darma-loader-three-dots-bricks{
  --td-dot: calc(var(--loader-size, 56px) / 5.6);
  --td-gap: calc(var(--loader-size, 56px) / 12);
  display:inline-flex;
  align-items:center;
  justify-content:center;
  gap:var(--td-gap);
  width:var(--loader-size, 56px);
  height:var(--loader-size, 56px);
}
.darma-loader-three-dots-bricks i{
  width:var(--td-dot);
  height:var(--td-dot);
  border-radius:50%;
  background-color:var(--loader-color, #6366f1);
}
.darma-loader-three-dots-bricks i{border-radius:calc(var(--loader-size, 56px) / 28);animation:darma-loader-three-dots-bricks-td-bricks var(--loader-speed, 2s) infinite ease}
.darma-loader-three-dots-bricks i:nth-child(2){animation-delay:calc(var(--loader-speed, 2s) / 4)}
.darma-loader-three-dots-bricks i:nth-child(3){animation-delay:calc(var(--loader-speed, 2s) / 2)}
@keyframes darma-loader-three-dots-bricks-td-bricks{
  0%,100%{transform:translateY(0)}
  25%{transform:translateY(calc(var(--td-dot) * -1))}
  50%{transform:translateY(0)}
}

